func init() {
	// Runtime.Apply wraps these exact static validation errors. Register the
	// complete messages instead of translating arbitrary suffixes at runtime.
	for _, source := range []string{
		"The built-in direct outbound must remain enabled with type direct and Internet access.",
		"revision must be positive",
		"admin listener is required",
		"allowed_clients must not be empty",
		"management token and TLS file paths are required",
		"proxy username and password file must be configured together",
		"WARP proxy_address is required",
		"WireGuard config_file is required",
		"tailscale state_dir is required",
		"default_outbound must refer to an enabled outbound",
		"adaptive candidates must not be empty",
		"adaptive rule cannot also set outbound",
		"invalid adaptive settings or probe budget exceeds limits",
	} {
		coreCatalog["Configuration validation failed: "+source] = "設定驗證失敗：" + coreCatalog[source]
	}
}
